package com.wissenup.domain.fee.entity; import jakarta.persistence.*;import lombok.*;import java.time.*;import java.math.*;
@Entity @Table(name="fee_payments") @Getter@Setter@Builder@NoArgsConstructor@AllArgsConstructor public class FeePayment{@Id@GeneratedValue(strategy=GenerationType.IDENTITY)private Long paymentId;@Column(name="organization_id")private Long organizationId;@Column(name="student_fee_id")private Long studentFeeId;@Column(name="student_id")private Long studentId;@Column(name="amount_paid")private BigDecimal amountPaid;@Column(name="refunded_amount")private BigDecimal refundedAmount;@Column(name="payment_date")private LocalDate paymentDate;@Column(name="payment_mode")private String paymentMode;@Column(name="transaction_reference")private String transactionReference;@Column(name="receipt_number")private String receiptNumber;private String remarks;@Column(name="payment_status")private String paymentStatus;@Column(name="created_at")private LocalDateTime createdAt;@Column(name="created_by")private Long createdBy;@PrePersist void c(){if(refundedAmount==null)refundedAmount=BigDecimal.ZERO;if(paymentStatus==null)paymentStatus="COMPLETED";if(createdAt==null)createdAt=LocalDateTime.now();}}
